public class PrimitiveListView {
 public static Map<String,Object> inspect(List<Object> input) {return boxed(input);}
 private static Map<String,Object> boxed(Object input) {
  Map<String,Object> payload=new Map<String,Object>{'size'=>((List<Object>)input).size()};
  try {Account value=(Account)input;payload.put('castAccepted',true);payload.put('resultNull',value==null);}
  catch(Exception problem) {payload.put('castAccepted',false);payload.put('castType',problem.getTypeName());payload.put('castMessage',problem.getMessage());String element=problem.getMessage().substringBetween('List<','>');payload.put('element',element);try{Type token=Type.forName(element);payload.put('reflectedNull',token==null);if(token!=null)payload.put('reflectedName',token.getName());}catch(Exception reflection){payload.put('reflectionType',reflection.getTypeName());payload.put('reflectionMessage',reflection.getMessage());}}
  return payload;
 }
}

